using Microsoft.AspNetCore.Identity;
using Microsoft.Data.SqlClient;
using System.Text.Json.Nodes;
namespace MyProjectManagement;
public static class Bootstrap {
 public static async Task Run(IServiceProvider services,string[] args){int pos=Array.IndexOf(args,"--create-admin");if(pos<0||pos+1>=args.Length)throw new Exception("Usage: dotnet MyProjectManagement.dll --create-admin owner@company.com");var email=args[pos+1].Trim();if(!System.Net.Mail.MailAddress.TryCreate(email,out var parsed)||parsed.Address!=email)throw new Exception("Enter a valid owner email");Console.Write("Owner display name: ");string name=Console.ReadLine()?.Trim()??"Project manager";Console.Write("New owner password (15+ characters, hidden): ");string password=ReadPassword();Console.Write("Confirm password (hidden): ");string confirm=ReadPassword();if(password!=confirm)throw new Exception("Passwords must match");PasswordPolicy.Validate(password,services.GetRequiredService<IConfiguration>());var db=services.GetRequiredService<Db>();await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await using(var q=new SqlCommand("SELECT COUNT(*) FROM dbo.AppUsers WITH (UPDLOCK,HOLDLOCK)",c,tx)){if(Convert.ToInt32(await q.ExecuteScalarAsync())!=0)throw new Exception("Owner initialization is allowed only when AppUsers is empty");}var wid=Guid.NewGuid();var uid=Guid.NewGuid();var user=new AppUser(uid,wid,email,"",true,null,false,false,0,null,"");var hash=services.GetRequiredService<PasswordHasher<AppUser>>().HashPassword(user,password);var roles=new JsonObject();string[] flags=["viewAllProjects","createProjects","assignTasks","managePlans","manageModules","scheduleMeetings","updateTasks","manageTeam","exportReports","deleteTasks","deleteProjects","deleteMeetings","manageModuleMaster","manageActivityMaster","correctActualTimes","manageCustomers","manageWeeklyPlans","rescheduleAllocations","manageClientHours","viewAmcCompliance"];
 foreach(var role in new[]{"Project manager","Project lead","ERP consultant"}){var values=new JsonObject();foreach(var flag in flags)values[flag]=role=="Project manager"||role=="Project lead"&&new[]{"assignTasks","managePlans","manageModules","scheduleMeetings","updateTasks","exportReports","manageWeeklyPlans","rescheduleAllocations","viewAmcCompliance"}.Contains(flag)||role=="ERP consultant"&&flag=="updateTasks";roles[role]=values;}
 var settings=new JsonObject{["customers"]=new JsonArray(),["rolePermissions"]=roles,["roleMaster"]=MasterData.Roles(new JsonObject()),["activityTypes"]=ActivityTypes.Catalog(new JsonObject()),["moduleMaster"]=new JsonArray(),["activityMaster"]=new JsonArray()};ChangeRequests.Seed(settings);await Db.Exec(c,tx,"INSERT dbo.Workspaces(Id,Name,OwnerId,Revision,SettingsJson) VALUES(@w,@name,@u,0,@s)",("@w",wid),("@name",name==""?"My Project Management":name),("@u",uid),("@s",settings.ToJsonString()));await Db.Exec(c,tx,"INSERT dbo.AppUsers(Id,WorkspaceId,Email,EmailNormalized,PasswordHash,IsOwner,Disabled,MustChangePassword,FailedAttempts) VALUES(@u,@w,@e,@en,@h,1,0,0,0)",("@u",uid),("@w",wid),("@e",email),("@en",email.ToUpperInvariant()),("@h",hash));await tx.CommitAsync();Console.WriteLine("Owner account and empty workspace created. Sign in, then import your browser backup.");}
 static string ReadPassword(){if(Console.IsInputRedirected)throw new Exception("Run owner initialization in an interactive terminal. Do not put passwords in command arguments or files.");var chars=new List<char>();ConsoleKeyInfo key;while((key=Console.ReadKey(true)).Key!=ConsoleKey.Enter){if(key.Key==ConsoleKey.Backspace){if(chars.Count>0)chars.RemoveAt(chars.Count-1);}else if(!char.IsControl(key.KeyChar))chars.Add(key.KeyChar);}Console.WriteLine();return new string(chars.ToArray());}
}
